import {
  Injectable,
  computed,
  inject,
  signal
} from '@angular/core';

import type { UserGameFilterPreferencesDto } from '../../../core/contracts/activity.interface';
import type {
  ProfileExtDto,
  UserDto,
  UserImpressionsDto,
  UserPaymentTotalsDto,
  UserRealtimeLongPollResponseDto
} from '../../../core/contracts/user.interface';
import {
  UserRealtimeUiConverter
} from '../../converters/user-realtime-ui.converter';
import { hasOperatorRole } from '../../../core/common/user-role';
import {
  ACTIVITY_COUNTER_KEYS,
  type ActivityCounterSyncToken,
  type ActivityCounters
} from './activity.store';
import {
  adminUserFromProfile,
  cloneAssetCounters,
  cloneEventCounters,
  cloneEventFeedbackCounters,
  cloneImpressions,
  cloneProfileExt,
  cloneUserProfile,
  normalizeCounterValue,
  normalizeFilterPreferences
} from './app-context-store.utils';
import {
  ActivityStore
} from './activity.store';

export interface UserImpressionChangeFlags {
  host: boolean;
  member: boolean;
}

export interface UserProfileAdminUserDto {
  id: string;
  name: string;
  initials: string;
  email: string;
  headline?: string | null;
  about?: string | null;
  images?: string[] | null;
}

export const DEFAULT_USER_IMPRESSION_CHANGE_FLAGS: UserImpressionChangeFlags = {
  host: false,
  member: false
};

export interface UserRealtimeProfilePatch {
  counterPatch: Partial<ActivityCounters>;
  impressions: UserImpressionsDto;
  changeFlags: UserImpressionChangeFlags | null;
  clearChangeFlags: boolean;
  paymentTotals: UserPaymentTotalsDto | null;
}

export interface UserProfileSaveSignal {
  revision: number;
  userId: string;
  profile: UserDto;
  previousProfile: UserDto | null;
}

@Injectable({
  providedIn: 'root'
})
export class UserProfileStore {
  private readonly activityStore = inject(ActivityStore);
  private readonly _userProfilesByUserId = signal<Record<string, UserDto>>({});
  private readonly _profileExtByUserId = signal<Record<string, ProfileExtDto>>({});
  private readonly _filterCountByUserId = signal<Record<string, number>>({});
  private readonly _filterPreferencesByUserId = signal<Record<string, UserGameFilterPreferencesDto>>({});
  private readonly _impressionsByUserId = signal<Record<string, UserImpressionsDto>>({});
  private readonly _impressionChangeFlagsByUserId = signal<Record<string, UserImpressionChangeFlags>>({});
  private readonly _activeUserId = signal<string>('');
  private readonly _profileSaved = signal<UserProfileSaveSignal | null>(null);
  private readonly realtimeCursorByUserId: Record<string, string> = {};
  private readonly realtimeSeenImpressionsCursorByUserId: Record<string, string> = {};
  private readonly realtimeIgnoreNextImpressionsSnapshotByUserId: Record<string, boolean> = {};
  private profileSavedRevision = 0;
  private realtimePollInFlight = false;

  readonly userProfilesByUserId = this._userProfilesByUserId.asReadonly();
  readonly profileExtByUserId = this._profileExtByUserId.asReadonly();
  readonly filterCountByUserId = this._filterCountByUserId.asReadonly();
  readonly filterPreferencesByUserId = this._filterPreferencesByUserId.asReadonly();
  readonly impressionsByUserId = this._impressionsByUserId.asReadonly();
  readonly impressionChangeFlagsByUserId = this._impressionChangeFlagsByUserId.asReadonly();
  readonly activeUserId = this._activeUserId.asReadonly();
  readonly profileSaved = this._profileSaved.asReadonly();
  readonly activeUserProfile = computed(() => {
    const normalizedUserId = this._activeUserId().trim();
    if (!normalizedUserId) {
      return null;
    }
    const user = this._userProfilesByUserId()[normalizedUserId];
    return user ? cloneUserProfile(user) : null;
  });
  readonly activeNotificationDevices = computed(() => this.activeUserProfile()?.notificationDevices ?? []);

  applyUserRealtimeLocation(userId: string, coordinates: UserRealtimeLongPollResponseDto['locationCoordinates']): void {
    if (coordinates === undefined) return;
    const current = this._userProfilesByUserId()[userId];
    if (!current || (current.locationCoordinates?.latitude === coordinates?.latitude
      && current.locationCoordinates?.longitude === coordinates?.longitude)) return;
    this._userProfilesByUserId.update(state => ({ ...state, [userId]: {
      ...current, locationCoordinates: coordinates ? { ...coordinates } : undefined
    } }));
  }

  applyUserRealtimeNotificationDevices(userId: string, devices: UserDto['notificationDevices']): void {
    if (!devices) return;
    const current = this._userProfilesByUserId()[userId];
    if (!current) return;
    if (JSON.stringify(current.notificationDevices) === JSON.stringify(devices)) return;
    this._userProfilesByUserId.update(state => ({ ...state, [userId]: {
      ...current, notificationDevices: devices.map(device => ({ ...device }))
    } }));
  }
  readonly activeUserProfileExt = computed(() => {
    const normalizedUserId = this._activeUserId().trim();
    if (!normalizedUserId) {
      return null;
    }
    return this._profileExtByUserId()[normalizedUserId] ?? null;
  });
  readonly activeUserIsAdmin = computed(() =>
    this.isAdminUserProfile(this.activeUserProfile(), this._activeUserId())
  );
  readonly activeUserIsOperator = computed(() =>
    hasOperatorRole(this.activeUserProfile())
  );
  readonly activeUserLocationMissing = computed(() => {
    const user = this.activeUserProfile();
    if (!user || this.activeUserIsAdmin() || this.activeUserIsOperator()) return false;
    return !Number.isFinite(user.locationCoordinates?.latitude)
      || !Number.isFinite(user.locationCoordinates?.longitude);
  });
  readonly activeAdminUser = computed(() =>
    this.activeUserIsAdmin() ? adminUserFromProfile(this.activeUserProfile()) : null
  );

  getActiveUserId(): string {
    return this._activeUserId();
  }

  setActiveUserId(userId: string): void {
    const normalizedUserId = userId.trim();
    this._activeUserId.set(normalizedUserId);
  }

  getUserProfile(userId: string): UserDto | null {
    const normalizedUserId = userId.trim();
    if (!normalizedUserId) {
      return null;
    }
    const user = this._userProfilesByUserId()[normalizedUserId];
    return user ? cloneUserProfile(user) : null;
  }

  setUserProfile(user: UserDto): void {
    const normalizedUserId = user.id.trim();
    if (!normalizedUserId) {
      return;
    }
    this._userProfilesByUserId.update(state => ({
      ...state,
      [normalizedUserId]: cloneUserProfile({
        ...user,
        id: normalizedUserId
      })
    }));
  }

  setActiveUserProfile(user: UserDto): void {
    const normalizedUserId = user.id.trim();
    if (!normalizedUserId) {
      return;
    }
    const normalizedUser = cloneUserProfile({
      ...user,
      id: normalizedUserId
    });
    this._userProfilesByUserId.update(state => ({
      ...state,
      [normalizedUserId]: normalizedUser
    }));
    this._activeUserId.set(normalizedUserId);
    this._impressionsByUserId.update(state => {
      if (normalizedUser.impressions) {
        return {
          ...state,
          [normalizedUserId]: cloneImpressions(normalizedUser.impressions)
        };
      }
      if (!Object.prototype.hasOwnProperty.call(state, normalizedUserId)) {
        return state;
      }
      const { [normalizedUserId]: _removed, ...rest } = state;
      return rest;
    });
  }

  getProfileExt(userId: string): ProfileExtDto | null {
    const normalizedUserId = userId.trim();
    if (!normalizedUserId) {
      return null;
    }
    const profileExt = this._profileExtByUserId()[normalizedUserId];
    return profileExt ? cloneProfileExt(profileExt) : null;
  }

  setProfileExt(profileExt: ProfileExtDto): void {
    const normalizedUserId = profileExt.profile.id.trim();
    if (!normalizedUserId) {
      return;
    }
    const normalizedProfileExt = cloneProfileExt({
      ...profileExt,
      profile: {
        ...profileExt.profile,
        id: normalizedUserId
      }
    });
    this._profileExtByUserId.update(state => ({
      ...state,
      [normalizedUserId]: normalizedProfileExt
    }));
    this.setUserProfile(normalizedProfileExt.profile);
  }

  emitProfileSaved(profile: UserDto, previousProfile: UserDto | null = null): void {
    const normalizedUserId = profile.id.trim();
    if (!normalizedUserId) {
      return;
    }
    this._profileSaved.set({
      revision: ++this.profileSavedRevision,
      userId: normalizedUserId,
      profile: cloneUserProfile({
        ...profile,
        id: normalizedUserId
      }),
      previousProfile: previousProfile
        ? cloneUserProfile(previousProfile)
        : null
    });
  }

  patchActiveUserProfile(
    patch: Partial<Omit<UserDto, 'id'>> | ((current: UserDto) => Partial<Omit<UserDto, 'id'>>)
  ): UserDto | null {
    const current = this.activeUserProfile();
    if (!current) {
      return null;
    }
    const resolvedPatch = typeof patch === 'function' ? patch(current) : patch;
    const nextUser: UserDto = {
      ...current,
      ...resolvedPatch,
      id: current.id
    };
    this.setUserProfile(nextUser);
    return this.getUserProfile(current.id);
  }

  patchUserActivityCounters(userId: string, patch: Partial<ActivityCounters>): UserDto | null {
    const normalizedUserId = userId.trim();
    if (!normalizedUserId) {
      return null;
    }
    const currentUser = this._userProfilesByUserId()[normalizedUserId] ?? null;
    if (!currentUser) {
      return null;
    }
    const nextUser = cloneUserProfile({
      ...currentUser,
      activities: this.applyActivityCounterPatch(currentUser.activities, patch)
    });
    this._userProfilesByUserId.update(state => ({
      ...state,
      [normalizedUserId]: nextUser
    }));
    this._profileExtByUserId.update(state => {
      const currentExt = state[normalizedUserId];
      if (!currentExt) {
        return state;
      }
      return {
        ...state,
        [normalizedUserId]: {
          ...currentExt,
          profile: nextUser
        }
      };
    });
    return cloneUserProfile(nextUser);
  }

  patchUserNotificationPreferences(userId: string, muted: boolean): UserDto | null {
    const normalizedUserId = userId.trim();
    if (!normalizedUserId) {
      return null;
    }
    const currentUser = this._userProfilesByUserId()[normalizedUserId] ?? null;
    if (!currentUser) {
      return null;
    }
    const nextUser = cloneUserProfile({
      ...currentUser,
      notificationPreferences: {
        ...currentUser.notificationPreferences,
        muted: muted === true
      }
    });
    this._userProfilesByUserId.update(state => ({
      ...state,
      [normalizedUserId]: nextUser
    }));
    this._profileExtByUserId.update(state => {
      const currentExt = state[normalizedUserId];
      if (!currentExt) {
        return state;
      }
      return {
        ...state,
        [normalizedUserId]: {
          ...currentExt,
          profile: nextUser
        }
      };
    });
    return cloneUserProfile(nextUser);
  }

  getActiveAdminUser(): UserProfileAdminUserDto | null {
    return this.activeAdminUser();
  }

  isAdminUserProfile(user: UserDto | null | undefined, fallbackUserId = ''): boolean {
    const normalizedUserId = `${user?.id ?? fallbackUserId ?? ''}`.trim();
    return user?.admin === true
      || user?.hostTier === 'Admin'
      || user?.statusText === 'Admin workspace'
      || normalizedUserId === 'admin'
      || normalizedUserId.startsWith('admin-');
  }

  clearUserProfile(userId: string): void {
    const normalizedUserId = userId.trim();
    if (!normalizedUserId) {
      return;
    }
    this._userProfilesByUserId.update(state => {
      if (!Object.prototype.hasOwnProperty.call(state, normalizedUserId)) {
        return state;
      }
      const { [normalizedUserId]: _removed, ...rest } = state;
      return rest;
    });
  }

  getUserFilterCountOverride(userId: string): number | null {
    const normalizedUserId = userId.trim();
    if (!normalizedUserId) {
      return null;
    }
    const value = this._filterCountByUserId()[normalizedUserId];
    if (!Number.isFinite(value)) {
      return null;
    }
    return normalizeCounterValue(value);
  }

  setUserFilterCountOverride(userId: string, value: number): void {
    const normalizedUserId = userId.trim();
    if (!normalizedUserId) {
      return;
    }
    const normalizedValue = normalizeCounterValue(value);
    this._filterCountByUserId.update(state => ({
      ...state,
      [normalizedUserId]: normalizedValue
    }));
  }

  clearUserFilterCountOverride(userId: string): void {
    const normalizedUserId = userId.trim();
    if (!normalizedUserId) {
      return;
    }
    this._filterCountByUserId.update(state => {
      if (!Object.prototype.hasOwnProperty.call(state, normalizedUserId)) {
        return state;
      }
      const { [normalizedUserId]: _removed, ...rest } = state;
      return rest;
    });
  }

  resolveUserFilterCount(userId: string, fallbackValue: number): number {
    const override = this.getUserFilterCountOverride(userId);
    if (override !== null) {
      return override;
    }
    return normalizeCounterValue(fallbackValue);
  }

  getUserFilterPreferences(userId: string): UserGameFilterPreferencesDto | null {
    const normalizedUserId = userId.trim();
    if (!normalizedUserId) {
      return null;
    }
    const preferences = this._filterPreferencesByUserId()[normalizedUserId];
    if (!preferences) {
      return null;
    }
    return { ...preferences };
  }

  resolveUserFilterPreferences<T extends UserGameFilterPreferencesDto>(userId: string, fallback: T): T {
    const normalizedFallback = normalizeFilterPreferences(fallback) as T;
    const preferences = this.getUserFilterPreferences(userId);
    if (!preferences) {
      return { ...normalizedFallback };
    }
    return normalizeFilterPreferences({
      ...normalizedFallback,
      ...preferences
    }) as T;
  }

  setUserFilterPreferences(userId: string, preferences: UserGameFilterPreferencesDto): void {
    const normalizedUserId = userId.trim();
    if (!normalizedUserId) {
      return;
    }
    this._filterPreferencesByUserId.update(state => ({
      ...state,
      [normalizedUserId]: normalizeFilterPreferences(preferences)
    }));
  }

  clearUserFilterPreferences(userId: string): void {
    const normalizedUserId = userId.trim();
    if (!normalizedUserId) {
      return;
    }
    this._filterPreferencesByUserId.update(state => {
      if (!Object.prototype.hasOwnProperty.call(state, normalizedUserId)) {
        return state;
      }
      const { [normalizedUserId]: _removed, ...rest } = state;
      return rest;
    });
  }

  getUserImpressions(userId: string): UserImpressionsDto | null {
    const normalizedUserId = userId.trim();
    if (!normalizedUserId) {
      return null;
    }
    const impressions = this._impressionsByUserId()[normalizedUserId];
    if (!impressions) {
      return null;
    }
    return cloneImpressions(impressions);
  }

  setUserImpressions(userId: string, impressions: UserImpressionsDto): void {
    const normalizedUserId = userId.trim();
    if (!normalizedUserId) {
      return;
    }
    this._impressionsByUserId.update(state => ({
      ...state,
      [normalizedUserId]: cloneImpressions(impressions)
    }));
  }

  clearUserImpressions(userId: string): void {
    const normalizedUserId = userId.trim();
    if (!normalizedUserId) {
      return;
    }
    this._impressionsByUserId.update(state => {
      if (!Object.prototype.hasOwnProperty.call(state, normalizedUserId)) {
        return state;
      }
      const { [normalizedUserId]: _removed, ...rest } = state;
      return rest;
    });
  }

  getUserImpressionChangeFlags(userId: string): UserImpressionChangeFlags {
    const normalizedUserId = userId.trim();
    if (!normalizedUserId) {
      return { ...DEFAULT_USER_IMPRESSION_CHANGE_FLAGS };
    }
    const flags = this._impressionChangeFlagsByUserId()[normalizedUserId];
    if (!flags) {
      return { ...DEFAULT_USER_IMPRESSION_CHANGE_FLAGS };
    }
    return {
      host: flags.host === true,
      member: flags.member === true
    };
  }

  setUserImpressionChangeFlags(userId: string, flags: UserImpressionChangeFlags): void {
    const normalizedUserId = userId.trim();
    if (!normalizedUserId) {
      return;
    }
    const normalizedFlags: UserImpressionChangeFlags = {
      host: flags.host === true,
      member: flags.member === true
    };
    this._impressionChangeFlagsByUserId.update(state => ({
      ...state,
      [normalizedUserId]: normalizedFlags
    }));
  }

  clearUserImpressionChangeFlags(userId: string): void {
    const normalizedUserId = userId.trim();
    if (!normalizedUserId) {
      return;
    }
    this._impressionChangeFlagsByUserId.update(state => {
      if (!Object.prototype.hasOwnProperty.call(state, normalizedUserId)) {
        return state;
      }
      const { [normalizedUserId]: _removed, ...rest } = state;
      return rest;
    });
  }

  getUserRealtimeCursor(userId: string): string | null {
    const normalizedUserId = userId.trim();
    if (!normalizedUserId) {
      return null;
    }
    return this.realtimeCursorByUserId[normalizedUserId] ?? null;
  }

  setUserRealtimePollInFlight(inFlight: boolean): void {
    this.realtimePollInFlight = inFlight;
  }

  markUserRealtimeImpressionsClosed(userId: string): void {
    const normalizedUserId = userId.trim();
    if (!normalizedUserId) {
      return;
    }
    const cursor = this.realtimeCursorByUserId[normalizedUserId] ?? '';
    if (cursor) {
      this.realtimeSeenImpressionsCursorByUserId[normalizedUserId] = cursor;
    }
    if (this.realtimePollInFlight) {
      this.realtimeIgnoreNextImpressionsSnapshotByUserId[normalizedUserId] = true;
    }
  }

  applyUserRealtimeCounters(
    userId: string,
    snapshot: UserRealtimeLongPollResponseDto,
    counterSyncToken: ActivityCounterSyncToken
  ): boolean {
    const normalizedUserId = userId.trim();
    if (!normalizedUserId || counterSyncToken.userId !== normalizedUserId) {
      return false;
    }
    return this.activityStore.applyRealtimeCounterOverrides(
      counterSyncToken,
      UserRealtimeUiConverter.toCounterPatch(snapshot)
    );
  }

  applyUserRealtimeSnapshot(
    userId: string,
    snapshot: UserRealtimeLongPollResponseDto,
    counterSyncToken?: ActivityCounterSyncToken
  ): void {
    const normalizedUserId = userId.trim();
    if (!normalizedUserId) {
      return;
    }

    const nextCursor = typeof snapshot.cursor === 'string' ? snapshot.cursor.trim() : '';
    const shouldIgnoreNextImpressionsSnapshot = this.realtimeIgnoreNextImpressionsSnapshotByUserId[normalizedUserId] === true;
    const isSeenCursor = nextCursor.length > 0 && this.realtimeSeenImpressionsCursorByUserId[normalizedUserId] === nextCursor;
    const uiPatch = UserRealtimeUiConverter.convert({
      snapshot,
      currentChangeFlags: this.getUserImpressionChangeFlags(normalizedUserId),
      suppressImpressionBadges: shouldIgnoreNextImpressionsSnapshot || isSeenCursor
    });

    const countersApplied = counterSyncToken
      ? this.activityStore.applyRealtimeCounterOverrides(counterSyncToken, uiPatch.counterPatch)
      : (this.activityStore.patchUserCounterOverrides(normalizedUserId, uiPatch.counterPatch), true);
    this.applyUserRealtimePatch(normalizedUserId, {
      ...uiPatch,
      counterPatch: countersApplied ? uiPatch.counterPatch : {}
    });

    if (nextCursor.length > 0) {
      this.realtimeCursorByUserId[normalizedUserId] = nextCursor;
      if (shouldIgnoreNextImpressionsSnapshot) {
        this.realtimeSeenImpressionsCursorByUserId[normalizedUserId] = nextCursor;
      }
    }
    delete this.realtimeIgnoreNextImpressionsSnapshotByUserId[normalizedUserId];
  }

  applyUserRealtimeProfileStatus(
    userId: string,
    profileStatus: UserRealtimeLongPollResponseDto['profileStatus']
  ): void {
    const normalizedUserId = userId.trim();
    const normalizedStatus = `${profileStatus ?? ''}`.trim() as UserDto['profileStatus'];
    if (!normalizedUserId || !normalizedStatus) {
      return;
    }
    const currentUser = this._userProfilesByUserId()[normalizedUserId];
    if (!currentUser || currentUser.profileStatus === normalizedStatus) {
      return;
    }
    this._userProfilesByUserId.update(state => ({
      ...state,
      [normalizedUserId]: cloneUserProfile({
        ...currentUser,
        profileStatus: normalizedStatus
      })
    }));
  }

  private applyUserRealtimePatch(userId: string, patch: UserRealtimeProfilePatch): UserDto | null {
    const normalizedUserId = userId.trim();
    if (!normalizedUserId) {
      return null;
    }

    const impressions = cloneImpressions(patch.impressions);
    const currentUser = this._userProfilesByUserId()[normalizedUserId] ?? null;
    let nextUser: UserDto | null = null;

    if (currentUser) {
      nextUser = cloneUserProfile({
        ...currentUser,
        activities: this.applyActivityCounterPatch(currentUser.activities, patch.counterPatch),
        impressions,
        paymentTotals: patch.paymentTotals ?? currentUser.paymentTotals
      });
      this._userProfilesByUserId.update(state => ({
        ...state,
        [normalizedUserId]: nextUser as UserDto
      }));
    }

    this._impressionsByUserId.update(state => {
      return {
        ...state,
        [normalizedUserId]: impressions
      };
    });

    this._impressionChangeFlagsByUserId.update(state => {
      if (patch.clearChangeFlags) {
        if (!Object.prototype.hasOwnProperty.call(state, normalizedUserId)) {
          return state;
        }
        const { [normalizedUserId]: _removed, ...rest } = state;
        return rest;
      }
      if (!patch.changeFlags) {
        return state;
      }
      return {
        ...state,
        [normalizedUserId]: {
          host: patch.changeFlags.host === true,
          member: patch.changeFlags.member === true
        }
      };
    });

    return nextUser ? cloneUserProfile(nextUser) : null;
  }

  private applyActivityCounterPatch(
    current: UserDto['activities'],
    patch: Partial<ActivityCounters>
  ): UserDto['activities'] {
    const next: UserDto['activities'] = { ...current };
    for (const key of ACTIVITY_COUNTER_KEYS) {
      if (!Object.prototype.hasOwnProperty.call(patch, key)) {
        continue;
      }
      const value = patch[key];
      if (!Number.isFinite(value)) {
        continue;
      }
      next[key] = normalizeCounterValue(value);
    }
    if (patch.event) {
      next.event = cloneEventCounters(patch.event);
    }
    if (patch.asset) {
      next.asset = cloneAssetCounters(patch.asset);
    }
    if (patch.eventFeedback) {
      next.eventFeedback = cloneEventFeedbackCounters(patch.eventFeedback);
    }
    return next;
  }
}
